# Generated by build.py from recipe.yml for recipe http-give-up-within-a-time-budget. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"delay;ms=1500"', '--fault', '"error;scheme=http;reply=503"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --no-progress-meter -f --retry 10 --retry-delay 1 --retry-max-time 5 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt } finally { Stop-Process $server0 }
